export const TIME_LIMIT_OPTIONS = [20, 25, 30, 0];
export const TIME_LIMIT_LABELS = ['20s', '25s', '30s', '∞ ไม่จำกัด'];

export interface CategoryOption {
  id: string;
  type: 'main' | 'preset';
  thaiName: string;
  emoji: string;
  badge: string;
  description: string;
  region: ArtistRegion | 'all';
  category: Category;
}

const MAIN_CATEGORY_OPTIONS: CategoryOption[] = CATEGORIES.map((cat) => {
  let region: ArtistRegion | 'all' = 'all';
  if (cat.id === 'thai_hits' || cat.id === 'tpop_indie' || cat.id === '90s_2000s' || cat.id === 'lukthung_lifesong') {
    region = 'thai';
  } else if (cat.id === 'billboard_hot_100') {
    region = 'inter';
  } else if (cat.id === 'kpop_mega_hits') {
    region = 'kpop';
  } else if (cat.id === 'anime_jpop') {
    region = 'anime_jpop';
  }

  return {
    id: cat.id,
    type: 'main',
    thaiName: cat.thaiName,
    emoji: cat.emoji,
    badge: cat.badge,
    description: cat.description,
    region,
    category: {
      ...cat,
      modeType: 'standard'
    }
  };
});

const PRESET_CATEGORY_OPTIONS: CategoryOption[] = ARTIST_PRESETS.map((pr) => {
  return {
    id: pr.id,
    type: 'preset',
    thaiName: pr.title,
    emoji: pr.title.split(' ')[0] || '⚡',
    badge: 'จัดชุดด่วน',
    description: pr.subtitle || pr.artists.slice(0, 6).join(', '),
    region: pr.region,
    category: {
      id: pr.id,
      name: pr.title,
      thaiName: pr.title,
      emoji: pr.title.split(' ')[0] || '⚡',
      badge: 'จัดชุดด่วน',
      description: pr.subtitle || pr.artists.slice(0, 6).join(', '),
      gradient: 'from-orange-500 to-amber-600',
      searchQueries: pr.artists,
      selectedArtists: pr.artists,
      modeType: 'preset'
    }
  };
});

const ALL_CATEGORY_OPTIONS: CategoryOption[] = [...MAIN_CATEGORY_OPTIONS, ...PRESET_CATEGORY_OPTIONS];

// Single Category Selection (Persisted with storageService)
const [selectedCategoryId, setSelectedCategoryId] = useState<string>(() =>
  storageService.getSelectedCategoryId(CATEGORIES[0].id)
);
const [categoryTab, setCategoryTab] = useState<'all' | 'main' | 'presets'>('all');
const [regionFilter, setRegionFilter] = useState<ArtistRegion | 'all'>('all');
const [customCat, setCustomCat] = useState<Category | null>(null);
const [roundCount, setRoundCount] = useState<number>(() => currentTotalRounds ?? storageService.getTotalRounds(10));
const [answerMode, setAnswerMode] = useState<AnswerMode>(() => currentAnswerMode ?? storageService.getAnswerMode('multiple_choice'));

// Global Artists Multi-Select State
const [showGlobalPicker, setShowGlobalPicker] = useState<boolean>(false);
const [pickerPresetRegion, setPickerPresetRegion] = useState<ArtistRegion | undefined>(undefined);
const [customSelectedArtists, setCustomSelectedArtists] = useState<string[]>([]);

// Single effective category computed from selectedCategoryId (or custom global artists if chosen)
const effectiveCategory = useMemo<Category>(() => {
  if (customCat && customSelectedArtists.length > 0) {
    return customCat;
  }
  const found = ALL_CATEGORY_OPTIONS.find((item) => item.id === selectedCategoryId);
  if (found) {
    return found.category;
  }
  return CATEGORIES[0];
}, [customCat, customSelectedArtists, selectedCategoryId]);

// Filtered categories based on categoryTab and regionFilter
const filteredCategoryOptions = useMemo(() => {
  let list = ALL_CATEGORY_OPTIONS;
  if (categoryTab === 'main') {
    list = list.filter((it) => it.type === 'main');
  } else if (categoryTab === 'presets') {
    list = list.filter((it) => it.type === 'preset');
  }

  if (regionFilter !== 'all') {
    list = list.filter((it) => it.region === regionFilter || it.region === 'all');
  }
  return list;
}, [categoryTab, regionFilter]);

