// Game Settings (Persisted with storageService)
const [selectedCategoryIds, setSelectedCategoryIds] = useState<string[]>(() =>
  storageService.getSelectedCategoryIds([CATEGORIES[0].id])
);
const [customCat, setCustomCat] = useState<Category | null>(null);
const [roundCount, setRoundCount] = useState<number>(() => currentTotalRounds ?? storageService.getTotalRounds(10));
const [answerMode, setAnswerMode] = useState<AnswerMode>(() => currentAnswerMode ?? storageService.getAnswerMode('multiple_choice'));

// Global Artists Multi-Select State
const [showGlobalPicker, setShowGlobalPicker] = useState<boolean>(false);
const [pickerPresetRegion, setPickerPresetRegion] = useState<ArtistRegion | undefined>(undefined);
const [customSelectedArtists, setCustomSelectedArtists] = useState<string[]>([]);

// Active selected categories from grid
const activeCategories = useMemo(() => {
  const matched = CATEGORIES.filter((c) => selectedCategoryIds.includes(c.id));
  return matched.length > 0 ? matched : [CATEGORIES[0]];
}, [selectedCategoryIds]);

// Combined category computed from selectedCategoryIds (or custom global artists if chosen)
const effectiveCategory = useMemo<Category>(() => {
  if (customCat && customSelectedArtists.length > 0) {
    return customCat;
  }
  if (activeCategories.length === 1) {
    return {
      ...activeCategories[0],
      modeType: 'standard'
    };
  }
  const allQueries = Array.from(new Set(activeCategories.flatMap((c) => c.searchQueries)));
  const emojis = activeCategories.map((c) => c.emoji).join(' ');
  const isAll = activeCategories.length === CATEGORIES.length;

  return {
    id: 'multi_' + activeCategories.map((c) => c.id).join('_'),
    name: 'Combined Categories',
    thaiName: isAll
      ? '🎲 ผสมทุกแนวเพลง (8 หมวด)'
      : `ผสม ${activeCategories.length} หมวด (${emojis})`,
    emoji: isAll ? '🎲' : '🎵',
    badge: isAll ? 'ทุกแนวเพลง' : `${activeCategories.length} หมวด`,
    description: activeCategories.map((c) => c.thaiName.replace(/^[^\s]+\s+/, '')).join(' • '),
    gradient: 'from-orange-500 to-indigo-600',
    searchQueries: allQueries,
    includedCategories: activeCategories,
    modeType: 'combined'
  };
}, [activeCategories, customCat, customSelectedArtists]);

