const handleToggleCategory = (cat: Category) => {
  soundFX.playClick();
  setCustomCat(null);
  setCustomSelectedArtists([]);

  if (cat.id === 'all_stars') {
    if (selectedCategoryIds.length === CATEGORIES.length) {
      const next = [CATEGORIES[0].id];
      setSelectedCategoryIds(next);
      storageService.setSelectedCategoryIds(next);
    } else {
      const next = CATEGORIES.map((c) => c.id);
      setSelectedCategoryIds(next);
      storageService.setSelectedCategoryIds(next);
    }
    return;
  }

  let next: string[];
  if (selectedCategoryIds.includes(cat.id)) {
    if (selectedCategoryIds.length === 1) {
      return; // Keep at least one category selected
    }
    next = selectedCategoryIds.filter((id) => id !== cat.id);
  } else {
    next = [...selectedCategoryIds, cat.id];
  }
  setSelectedCategoryIds(next);
  storageService.setSelectedCategoryIds(next);
};

const handleToggleAllCategories = () => {
  soundFX.playClick();
  setCustomCat(null);
  setCustomSelectedArtists([]);

  if (selectedCategoryIds.length === CATEGORIES.length) {
    const next = [CATEGORIES[0].id];
    setSelectedCategoryIds(next);
    storageService.setSelectedCategoryIds(next);
  } else {
    const next = CATEGORIES.map((c) => c.id);
    setSelectedCategoryIds(next);
    storageService.setSelectedCategoryIds(next);
  }
};

